using InventorySystem.Domain.Entities; using InventorySystem.Infrastructure.Services; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc;
namespace InventorySystem.API.Controllers;
[ApiController][Route("api/auth")] public class AuthController(UserManager<AppUser> users,SignInManager<AppUser> signIn,TokenService tokens) : ControllerBase { public record LoginRequest(string Email,string Password); public record RegisterRequest(string Email,string Password,string FullName); [HttpPost("login")] public async Task<IActionResult> Login(LoginRequest r){var u=await users.FindByEmailAsync(r.Email); if(u is null||!await signIn.CheckPasswordSignInAsync(u,r.Password,false).ContinueWith(x=>x.Result.Succeeded)) return Unauthorized(new{error="Invalid credentials."}); return Ok(new{token=await tokens.GenerateTokenAsync(u)});} [HttpPost("register")] public async Task<IActionResult> Register(RegisterRequest r){var u=new AppUser{UserName=r.Email,Email=r.Email,FullName=r.FullName}; var result=await users.CreateAsync(u,r.Password); if(!result.Succeeded)return BadRequest(result.Errors); await users.AddToRoleAsync(u,"Cashier"); return Ok(new{token=await tokens.GenerateTokenAsync(u)}); } }
